#[test]
fn every_catalog_service_s_own_address_leads_back_to_it() {
    for service in SERVICES {
        let url = Url::parse(service.url).unwrap();
        assert_eq!(for_url(&url).map(|s| s.id), Some(service.id), "{}", service.url);
        assert!(is_service_id(service.id));
    }
}

#[test]
fn catalog_ids_are_unique() {
    let mut ids: Vec<&str> = SERVICES.iter().map(|s| s.id).collect();
    ids.push(MUSIC_ID);
    let before = ids.len();
    ids.sort_unstable();
    ids.dedup();
    assert_eq!(ids.len(), before);
}

#[test]
fn parse_user_url_fuzz_seed_1_only_http_s_never_the_app_s_own_h() {
    let mut rng = Rng::new(31337);
    for _ in 0..2000 {
        let text = rng.text(&["https://", "http://", "ytmp.localhost", "www.", "example.com", "localhost"]);
        if let Some(url) = parse_user_url(&text) {
            assert!(matches!(url.scheme(), "http" | "https"), "{text:?}");
            let host = url.host_str().unwrap_or_default().to_ascii_lowercase();
            assert_ne!(host, HOME_HOST, "{text:?}");
            assert!(host.contains('.') || host == "localhost", "{text:?}");
        }
    }
}

